// =====================================================================================================================
// PORT NOTE (review R4 reproduction tests)
//   Upstream : oxia/internal/write_stream.go (streamWrapper.Send: a failed stream.Send marks the stream failed and returns the error),
//              common/rpc/oxia_error_streaming_client.go (OxiaErrorBidiStreamingClient.Send: constant.FromGrpcError(Send(request))),
//              grpc-go ClientStream.SendMsg contract: "On error, SendMsg aborts the stream. If the error was generated by the client,
//              the status is returned directly; otherwise, io.EOF is returned and the status of the stream may be discovered using RecvMsg."
//   Pinned at: 8456f61e1ada7b786f5ef17798b45fbc17d0d246
//   Intent   : When the SERVER has already ended a write stream (whatever status it ended with), Go's Send returns io.EOF, which
//              constant.IsRetryable accepts: the request is retried on a new stream.  The .NET wrapper must not leak the call's final
//              status from SendAsync: a non-Oxia, non-Unavailable status (Internal, Unknown, ...) is not retryable and turns a harmless
//              race (the request was handed to a stream that had just been terminated) into a failed write.
// =====================================================================================================================
using Grpc.Core;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using Oxia.Client.Internal;
using Oxia.Client.Tests.Proto;
using Oxia.Common.Constant;
using Oxia.Common.Proto;
using Oxia.Common.Rpc;
using Oxia.TestSupport;
using Xunit;

namespace Oxia.Client.Tests.Review;

public class R4_WriteStreamSendTests
{
    private static Metadata Headers(long shard) => new() { { "namespace", "ns" }, { "shard-id", shard.ToString() } };

    private static WriteRequest Req(string key)
    {
        var r = new WriteRequest();
        r.Puts.Add(new PutRequest { Key = key });
        return r;
    }

    [Fact]
    public async Task SendOnAStreamThatTheServerEndedWithAnInternalStatus_IsRetryableLikeGoIoEof()
    {
        var state = new MockOxiaState();
        await using var server = await TestGrpcServer.StartAsync(app => app.MapGrpcService<MockOxiaClientService>(), s => s.AddSingleton(state));
        await using var pool = new ClientPool(null, null);
        var rpc = pool.GetClientRpc(server.Address);

        using var call = rpc.WriteStream(Headers(100), default);
        await call.SendAsync(Req("fail-other"));   // the mock ends the stream with StatusCode.Internal
        var recvError = await Assert.ThrowsAnyAsync<Exception>(() => call.RecvAsync().AsTask().WaitAsync(TimeSpan.FromSeconds(10)));
        Assert.Equal(StatusCode.Internal, OxiaErrors.GrpcCode(recvError));   // the receive loop sees the real status ...

        // ... but a request handed to the ended stream gets Go's io.EOF (retryable), not the status of the ended call
        var sendError = await Assert.ThrowsAnyAsync<Exception>(() => call.SendAsync(Req("k")).AsTask());
        Assert.True(OxiaErrors.IsRetryable(sendError) && RpcProvider.IsRetryableShardRequest(sendError),
            "Send on a server-ended stream must be retryable (Go: io.EOF), got: " + sendError);
    }

    /// <summary>A write stream whose receive side is observed late: the real call has ended, but the receive loop has not reported it yet.</summary>
    private sealed class LateReceiveLoopCall(IWriteStreamCall inner) : IWriteStreamCall
    {
        public readonly TaskCompletionSource ReceiveLoopMayReport = new(TaskCreationOptions.RunContinuationsAsynchronously);

        /// <summary>Completes when the REAL call has ended on the client (its receive threw or returned null): from then on gRPC.NET
        /// fails writes. Lets a test wait for that fact instead of sleeping and hoping (the sleep flaked under load).</summary>
        public readonly TaskCompletionSource InnerReceiveFinished = new(TaskCreationOptions.RunContinuationsAsynchronously);

        public CancellationToken Context => inner.Context;
        public ValueTask SendAsync(WriteRequest request, CancellationToken ct = default) => inner.SendAsync(request, ct);
        public ValueTask CloseSendAsync() => inner.CloseSendAsync();
        public void Dispose() => inner.Dispose();

        public async ValueTask<WriteResponse?> RecvAsync(CancellationToken ct = default)
        {
            try
            {
                var response = await inner.RecvAsync(ct);
                if (response is null) InnerReceiveFinished.TrySetResult();
                return response;
            }
            catch
            {
                InnerReceiveFinished.TrySetResult();
                await ReceiveLoopMayReport.Task;
                throw;
            }
        }
    }

    /// <summary>
    /// The same through StreamWrapper, the object the shard batchers send through.  The wrapper converts a Send on a stream whose
    /// receive loop already drained it into io.EOF (its _ended guard), but a request that reaches gRPC in the window between the
    /// server ending the call and the receive loop noticing gets the call's final status.
    /// </summary>
    [Fact]
    public async Task StreamWrapperSend_InTheWindowBeforeTheReceiveLoopNoticesTheEnd_FailsWithARetryableError()
    {
        var state = new MockOxiaState();
        await using var server = await TestGrpcServer.StartAsync(app => app.MapGrpcService<MockOxiaClientService>(), s => s.AddSingleton(state));
        await using var pool = new ClientPool(null, null);
        var rpc = pool.GetClientRpc(server.Address);

        var cts = new CancellationTokenSource();
        var stream = new LateReceiveLoopCall(rpc.WriteStream(Headers(101), cts.Token));
        var wrapper = new StreamWrapper(101, server.Address, stream, cts);

        // the server ends the stream (Internal) after the first request; the receive loop is held back
        var first = wrapper.Send(default, () => Req("fail-other")).AsTask();
        await stream.InnerReceiveFinished.Task.WaitAsync(TimeSpan.FromSeconds(30));   // the call is over on the wire, the wrapper does not know yet

        var second = await Assert.ThrowsAnyAsync<Exception>(() => wrapper.Send(default, () => Req("k")).AsTask().WaitAsync(TimeSpan.FromSeconds(10)));
        try
        {
            Assert.True(RpcProvider.IsRetryableShardRequest(second), "the second request must be retried on a new stream (Go: io.EOF), got: " + second);
        }
        finally
        {
            stream.ReceiveLoopMayReport.TrySetResult();
            await Assert.ThrowsAnyAsync<Exception>(() => first.WaitAsync(TimeSpan.FromSeconds(10)));
        }
    }
}
